export default JSON.parse("{\"workId\":\"han-fei-zi\",\"chapter\":{\"id\":\"han-fei-zi_ch-48\",\"workId\":\"han-fei-zi\",\"order\":48,\"title\":\"八經\",\"difficulty\":4,\"estimatedMinutes\":10,\"passageIds\":[\"han-fei-zi_ch-48_p-1\",\"han-fei-zi_ch-48_p-2\",\"han-fei-zi_ch-48_p-3\",\"han-fei-zi_ch-48_p-4\",\"han-fei-zi_ch-48_p-5\",\"han-fei-zi_ch-48_p-6\",\"han-fei-zi_ch-48_p-7\",\"han-fei-zi_ch-48_p-8\",\"han-fei-zi_ch-48_p-9\",\"han-fei-zi_ch-48_p-10\",\"han-fei-zi_ch-48_p-11\",\"han-fei-zi_ch-48_p-12\",\"han-fei-zi_ch-48_p-13\",\"han-fei-zi_ch-48_p-14\",\"han-fei-zi_ch-48_p-15\"],\"tags\":[\"法家\",\"帝王術\",\"法術勢\"]},\"passages\":[{\"id\":\"han-fei-zi_ch-48_p-1\",\"chapterId\":\"han-fei-zi_ch-48\",\"order\":1,\"canonicalText\":\"一、凡治天下，必因人情。人情者，有好惡，故賞罰可用；賞罰可用則禁令可立而治道具矣。君執柄以處勢，故令行禁止。柄者，殺生之制也；勢者，勝眾之資也。廢置無度則權瀆，賞罰下共則威分。是以明主不懷愛而聽，不留說而計。故聽言不參則權分乎姦，智力不用則君窮乎臣。故明主之行制也天，其用人也鬼。天則不非，鬼則不困。勢行教嚴逆而不違，毀譽一行而不議。故賞賢罰暴，舉善之至者也；賞暴罰賢，舉惡之至者也；是謂賞同罰異。賞莫如厚，使民利之；譽莫如美，使民榮之；誅莫如重，使民畏之；毀莫如惡，使民恥之。然後一行其法，禁誅於私。家不害功罪，賞罰必知之，知之道盡矣。\",\"sentenceIds\":[\"han-fei-zi_ch-48_p-1_s-1\",\"han-fei-zi_ch-48_p-1_s-2\",\"han-fei-zi_ch-48_p-1_s-3\",\"han-fei-zi_ch-48_p-1_s-4\",\"han-fei-zi_ch-48_p-1_s-5\",\"han-fei-zi_ch-48_p-1_s-6\",\"han-fei-zi_ch-48_p-1_s-7\",\"han-fei-zi_ch-48_p-1_s-8\",\"han-fei-zi_ch-48_p-1_s-9\",\"han-fei-zi_ch-48_p-1_s-10\",\"han-fei-zi_ch-48_p-1_s-11\",\"han-fei-zi_ch-48_p-1_s-12\",\"han-fei-zi_ch-48_p-1_s-13\",\"han-fei-zi_ch-48_p-1_s-14\",\"han-fei-zi_ch-48_p-1_s-15\",\"han-fei-zi_ch-48_p-1_s-16\",\"han-fei-zi_ch-48_p-1_s-17\",\"han-fei-zi_ch-48_p-1_s-18\",\"han-fei-zi_ch-48_p-1_s-19\",\"han-fei-zi_ch-48_p-1_s-20\",\"han-fei-zi_ch-48_p-1_s-21\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"一、凡治天下，必因人情。人情的人或事物，有好惡，所以賞賜恩惠刑罰制裁可用；賞賜恩惠刑罰制裁可用則禁令可立而且治道具矣。君主統治者執柄以處至高權力威勢，所以令行禁止。柄的人或事物，殺生的制啊；至高權力威勢的人或事物，勝眾的資啊。廢置無度則權瀆，賞賜恩惠刑罰制裁下共則威分。是以明主不懷愛而且聽，不留說而且計。所以聽言不參則權分乎姦，智力不用則君主統治者窮乎臣下僚屬。所以明主的行制啊天，他的用人啊鬼。天則不絕不是，鬼則不困。至高權力威勢行教嚴逆而且不違，毀譽一行而且不議。所以賞賜恩惠賢刑罰制裁暴，舉善的至的人或事物啊；賞賜恩惠暴刑罰制裁賢，舉惡的至的人或事物啊；是謂賞賜恩惠同刑罰制裁異。賞賜恩惠莫如厚，使民利的；譽莫如美，使民榮的；誅莫如重，使民畏的；毀莫如惡，使民恥的。然後一行他的國家法度法規，禁誅於私。家不害功罪，賞賜恩惠刑罰制裁必知的，知的道盡矣。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈八經〉（第 1 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一、凡治天下，必因人情」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一、凡治天下，必因人情。人情者，有好惡，故賞罰可用；……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-48_p-2\",\"chapterId\":\"han-fei-zi_ch-48\",\"order\":2,\"canonicalText\":\"因情\",\"sentenceIds\":[\"han-fei-zi_ch-48_p-2_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"因情。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈八經〉（第 2 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「因情」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「因情」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-48_p-3\",\"chapterId\":\"han-fei-zi_ch-48\",\"order\":3,\"canonicalText\":\"二、力不敵眾，智不盡物。與其用一人，不如用一國。故智力敵而羣物勝，揣中則私勞，不中則在過。下君盡己之能，中君盡人之力，上君盡人之智。是以事至而結智，一聽而公會。聽不一則後悖於前，後悖於前則愚智不分；不公會則猶豫而不斷，不斷則事留。自取一，則毋墮壑之累。故使之諷，諷定而怒。是以言陳之日，必有筴籍，結智者事發而驗，結能者功見而。謀成敗，成敗有徵，賞罰隨之。事成則君收其功，規敗則臣任其罪。君人者合符猶不親，而況於力乎？事智猶不親，而況於懸乎？故非用人也不取同，同則君怒。使人相用則君神，君神則下盡。下盡下，則臣、上不因君而主道畢矣。\",\"sentenceIds\":[\"han-fei-zi_ch-48_p-3_s-1\",\"han-fei-zi_ch-48_p-3_s-2\",\"han-fei-zi_ch-48_p-3_s-3\",\"han-fei-zi_ch-48_p-3_s-4\",\"han-fei-zi_ch-48_p-3_s-5\",\"han-fei-zi_ch-48_p-3_s-6\",\"han-fei-zi_ch-48_p-3_s-7\",\"han-fei-zi_ch-48_p-3_s-8\",\"han-fei-zi_ch-48_p-3_s-9\",\"han-fei-zi_ch-48_p-3_s-10\",\"han-fei-zi_ch-48_p-3_s-11\",\"han-fei-zi_ch-48_p-3_s-12\",\"han-fei-zi_ch-48_p-3_s-13\",\"han-fei-zi_ch-48_p-3_s-14\",\"han-fei-zi_ch-48_p-3_s-15\",\"han-fei-zi_ch-48_p-3_s-16\",\"han-fei-zi_ch-48_p-3_s-17\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"二、力不敵眾，智不盡物。與他的用一人，不如用一國。所以智力敵而且羣物勝，揣中則私勞，不中則在過。下君主統治者盡己的能，中君主統治者盡人的力，上君主統治者盡人的智。是以事至而且結智，一聽而且公會。聽不一則後悖於前，後悖於前則愚智不分；不公會則猶豫而且不斷，不斷則事留。自取一，則毋墮壑的累。所以使的諷，諷定而且怒。是以言陳的日，必有筴籍，結智的人或事物事發而且驗，結能的人或事物功見而且。謀成敗，成敗有徵，賞賜恩惠刑罰制裁隨的。事成則君主統治者收他的功，規敗則臣下僚屬任他的罪。君主統治者人的人或事物合符猶不親，而且況於力乎？事智猶不親，而且況於懸乎？所以絕不是用人啊不取同，同則君主統治者怒。使人相用則君主統治者神，君主統治者神則下盡。下盡下，則臣下僚屬、上不因君主統治者而且主道畢矣。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈八經〉（第 3 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「二、力不敵眾，智不盡物」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「二、力不敵眾，智不盡物。與其用一人，不如用一國。故智……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-48_p-4\",\"chapterId\":\"han-fei-zi_ch-48\",\"order\":4,\"canonicalText\":\"主道\",\"sentenceIds\":[\"han-fei-zi_ch-48_p-4_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"主道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈八經〉（第 4 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「主道」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「主道」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-48_p-5\",\"chapterId\":\"han-fei-zi_ch-48\",\"order\":5,\"canonicalText\":\"三、知臣主之異利者王，以為同者劫，與共事者殺。故明主審公私之分，審利害之地，姦乃無所乘。亂之所生六也：主母，後姬，子姓，弟兄，大臣，顯賢。任吏責臣，主母不放。禮施異等，後姬不疑。分勢不貳，庶適不爭。權籍不失，兄弟不侵。下不一門，大臣不擁。禁賞必行，顯賢不亂。臣有二因，謂外內也。外曰畏，內曰愛。所畏之求得，所愛之言聽，此亂臣之所因也。外國之置諸吏者，結誅親暱重帑，則外不籍矣。爵祿循功，請者俱罪，則內不因矣。外不籍，內不因，則姦宄塞矣。官襲節而進，以至大任，智也。其位至而任大者，以三節持之，曰質、曰鎮、曰固。親戚妻子，質也。爵祿厚而必，鎮也。參伍貴帑，固也。賢者止於質，貪饕化於鎮，姦邪窮於固。忍不制則下上，小不除則大誅，而名實當則徑之。生害事，死傷名，則行飲食；不然，而與其讎；此謂除陰姦也。醫曰詭，詭曰易。易功而賞，見罪而罰，而詭乃止。是非不泄，說諫不通，而易乃不用。父兄賢良播出曰遊禍，其患鄰敵多資。僇辱之人近習曰狎賊，其患發忿疑辱之心生。藏怒持罪而不發曰增亂，其患徼倖妄舉之人起。大臣兩重、提衡而不踦曰卷禍，其患家隆劫殺之難作。脫易不自神曰彈威，其患賊夫酖毒之亂起。此五患者，人主之不知，則有劫殺之事。廢置之事，生於內則治，生於外則亂。是以明主以功論之內，而以利資之外，故其國治而敵亂。即亂之道，臣憎則起外若眩，臣愛則起內若藥。\",\"sentenceIds\":[\"han-fei-zi_ch-48_p-5_s-1\",\"han-fei-zi_ch-48_p-5_s-2\",\"han-fei-zi_ch-48_p-5_s-3\",\"han-fei-zi_ch-48_p-5_s-4\",\"han-fei-zi_ch-48_p-5_s-5\",\"han-fei-zi_ch-48_p-5_s-6\",\"han-fei-zi_ch-48_p-5_s-7\",\"han-fei-zi_ch-48_p-5_s-8\",\"han-fei-zi_ch-48_p-5_s-9\",\"han-fei-zi_ch-48_p-5_s-10\",\"han-fei-zi_ch-48_p-5_s-11\",\"han-fei-zi_ch-48_p-5_s-12\",\"han-fei-zi_ch-48_p-5_s-13\",\"han-fei-zi_ch-48_p-5_s-14\",\"han-fei-zi_ch-48_p-5_s-15\",\"han-fei-zi_ch-48_p-5_s-16\",\"han-fei-zi_ch-48_p-5_s-17\",\"han-fei-zi_ch-48_p-5_s-18\",\"han-fei-zi_ch-48_p-5_s-19\",\"han-fei-zi_ch-48_p-5_s-20\",\"han-fei-zi_ch-48_p-5_s-21\",\"han-fei-zi_ch-48_p-5_s-22\",\"han-fei-zi_ch-48_p-5_s-23\",\"han-fei-zi_ch-48_p-5_s-24\",\"han-fei-zi_ch-48_p-5_s-25\",\"han-fei-zi_ch-48_p-5_s-26\",\"han-fei-zi_ch-48_p-5_s-27\",\"han-fei-zi_ch-48_p-5_s-28\",\"han-fei-zi_ch-48_p-5_s-29\",\"han-fei-zi_ch-48_p-5_s-30\",\"han-fei-zi_ch-48_p-5_s-31\",\"han-fei-zi_ch-48_p-5_s-32\",\"han-fei-zi_ch-48_p-5_s-33\",\"han-fei-zi_ch-48_p-5_s-34\",\"han-fei-zi_ch-48_p-5_s-35\",\"han-fei-zi_ch-48_p-5_s-36\",\"han-fei-zi_ch-48_p-5_s-37\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"三、知臣下僚屬主的異利的人或事物王，以為同的人或事物劫，與共事的人或事物殺。所以明主審公私的分，審利害的地，姦乃無所乘。亂的所生六啊：主母，後姬，子姓，弟兄，大臣下僚屬，顯賢。任吏責臣下僚屬，主母不放。禮施異等，後姬不疑。分至高權力威勢不貳，庶適不爭。權籍不失，兄弟不侵。下不一門，大臣下僚屬不擁。禁賞賜恩惠必行，顯賢不亂。臣下僚屬有二因，謂外內啊。外說道：畏，內說道：愛。所畏的求得，所愛的言聽，此亂臣下僚屬的所因啊。外國的置諸吏的人或事物，結誅親暱重帑，則外不籍矣。爵祿循功，請的人或事物俱罪，則內不因矣。外不籍，內不因，則姦宄塞矣。官襲節而且進，以至大任，智啊。他的位至而且任大的人或事物，以三節持的，說道：質、說道：鎮、說道：固。親戚妻子，質啊。爵祿厚而且必，鎮啊。參伍貴帑，固啊。賢的人或事物止於質，貪饕化於鎮，姦邪窮於固。忍不制則下上，小不除則大誅，而且名實當則徑的。生害事，死傷名，則行飲食；不然，而且與他的讎；此謂除陰姦啊。醫說道：詭，詭說道：易。易功而且賞賜恩惠，見罪而且刑罰制裁，而且詭乃止。是絕不是不泄，說諫不通，而且易乃不用。父兄賢良播出說道：遊禍，他的患鄰敵多資。僇辱的人近習說道：狎賊，他的患發忿疑辱的心生。藏怒持罪而且不發說道：增亂，他的患徼倖妄舉的人起。大臣下僚屬兩重、提衡而且不踦說道：卷禍，他的患家隆劫殺的難作。脫易不自神說道：彈威，他的患賊夫酖毒的亂起。此五患的人或事物，人主的不知，則有劫殺的事。廢置的事，生於內則治，生於外則亂。是以明主以功論的內，而且以利資的外，所以他的國治而且敵亂。即亂的道，臣下僚屬憎則起外若眩，臣下僚屬愛則起內若藥。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈八經〉（第 5 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「三、知臣主之異利者王，以為同者劫，與共事者殺」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「三、知臣主之異利者王，以為同者劫，與共事者殺。故明主……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-48_p-6\",\"chapterId\":\"han-fei-zi_ch-48\",\"order\":6,\"canonicalText\":\"起亂\",\"sentenceIds\":[\"han-fei-zi_ch-48_p-6_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"起亂。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈八經〉（第 6 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「起亂」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「起亂」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-48_p-7\",\"chapterId\":\"han-fei-zi_ch-48\",\"order\":7,\"canonicalText\":\"四、參伍之道：行參以謀多，揆伍以責失；行參必拆，揆伍必怒。不拆則瀆上，不怒則相和。拆之徵足以知多寡，怒之前不及其眾。觀聽之勢，其徵在比周而賞異也。誅毋謁而罪同。言會眾端，必揆之以地，謀之以天，驗之以物，參之以人。四徵者符，乃可以觀矣。參言以知其誠，易視以改其澤。執見以得非常。一用以務近習，重言以懼遠使，舉往以悉其前，即邇以知其內，疏置以知其外，握明以問所闇，詭使以絕黷泄，倒言以嘗所疑，論反以得陰姦，設諫以綱獨為，舉錯以觀姦動，明說以誘避過，卑適以觀直諂，宣聞以通未見，作鬥以散朋黨，深一以警眾心，泄異以易其慮。似類則合其參，陳過則明其固，知罪闢罪以止威，陰使時循以省衰，漸更以離通比，下約以侵其上，相室約其廷臣，廷臣約其官屬，兵士約其軍吏，遣使約其行介，縣令約其闢吏，郎中約其左右，後姬約其宮媛，此之謂條達之道。言通事泄則術不行。\",\"sentenceIds\":[\"han-fei-zi_ch-48_p-7_s-1\",\"han-fei-zi_ch-48_p-7_s-2\",\"han-fei-zi_ch-48_p-7_s-3\",\"han-fei-zi_ch-48_p-7_s-4\",\"han-fei-zi_ch-48_p-7_s-5\",\"han-fei-zi_ch-48_p-7_s-6\",\"han-fei-zi_ch-48_p-7_s-7\",\"han-fei-zi_ch-48_p-7_s-8\",\"han-fei-zi_ch-48_p-7_s-9\",\"han-fei-zi_ch-48_p-7_s-10\",\"han-fei-zi_ch-48_p-7_s-11\",\"han-fei-zi_ch-48_p-7_s-12\",\"han-fei-zi_ch-48_p-7_s-13\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"四、參伍的道：行參以謀多，揆伍以責失；行參必拆，揆伍必怒。不拆則瀆上，不怒則相和。拆的徵足以知多寡，怒的前不及他的眾。觀聽的至高權力威勢，他的徵在比周而且賞賜恩惠異啊。誅毋謁而且罪同。言會眾端，必揆的以地，謀的以天，驗的以物，參的以人。四徵的人或事物符，乃可以觀矣。參言以知他的誠，易視以改他的澤。執見以得絕不是常。一用以務近習，重言以懼遠使，舉往以悉他的前，即邇以知他的內，疏置以知他的外，握明以問所闇，詭使以絕黷泄，倒言以嘗所疑，論反以得陰姦，設諫以綱獨為，舉錯以觀姦動，明說以誘避過，卑適以觀直諂，宣聞以通未見，作鬥以散朋黨，深一以警眾心，泄異以易他的慮。似類則合他的參，陳過則明他的固，知罪闢罪以止威，陰使時循以省衰，漸更以離通比，下約以侵他的上，相室約他的廷臣下僚屬，廷臣下僚屬約他的官屬，兵士約他的軍吏，遣使約他的行介，縣令約他的闢吏，郎中約他的左右，後姬約他的宮媛，此的謂條達的道。言通事泄則御臣心術權謀不行。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈八經〉（第 7 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「四、參伍之道：行參以謀多，揆伍以責失」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「四、參伍之道：行參以謀多，揆伍以責失；行參必拆，揆伍……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-48_p-8\",\"chapterId\":\"han-fei-zi_ch-48\",\"order\":8,\"canonicalText\":\"立道\",\"sentenceIds\":[\"han-fei-zi_ch-48_p-8_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"立道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈八經〉（第 8 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「立道」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「立道」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-48_p-9\",\"chapterId\":\"han-fei-zi_ch-48\",\"order\":9,\"canonicalText\":\"五、明主，其務在周密。是以喜見則德償，怒見則威分。故明主之言隔塞而不通，周密而不見。故以一得十者下道也，以十得一者上道也。明主兼行上下，故姦無所失。伍、官、連、縣而鄰，謁過賞，失過誅。上之於下，下之於上，亦然。是故上下貴賤相畏以法，相誨以和。民之性，有生之實，有生之名。為君者有賢知之名，有賞罰之實。名實俱至，故福善必聞矣。\",\"sentenceIds\":[\"han-fei-zi_ch-48_p-9_s-1\",\"han-fei-zi_ch-48_p-9_s-2\",\"han-fei-zi_ch-48_p-9_s-3\",\"han-fei-zi_ch-48_p-9_s-4\",\"han-fei-zi_ch-48_p-9_s-5\",\"han-fei-zi_ch-48_p-9_s-6\",\"han-fei-zi_ch-48_p-9_s-7\",\"han-fei-zi_ch-48_p-9_s-8\",\"han-fei-zi_ch-48_p-9_s-9\",\"han-fei-zi_ch-48_p-9_s-10\",\"han-fei-zi_ch-48_p-9_s-11\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"五、明主，他的務在周密。是以喜見則德償，怒見則威分。所以明主的言隔塞而且不通，周密而且不見。所以以一得十的人或事物下道啊，以十得一的人或事物上道啊。明主兼行上下，所以姦無所失。伍、官、連、縣而且鄰，謁過賞賜恩惠，失過誅。上的於下，下的於上，亦然。正因為如此上下貴賤相畏以國家法度法規，相誨以和。民的性，有生的實，有生的名。為君主統治者的人或事物有賢知的名，有賞賜恩惠刑罰制裁的實。名實俱至，所以福善必聞矣。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈八經〉（第 9 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「五、明主，其務在周密」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「五、明主，其務在周密。是以喜見則德償，怒見則威分。故……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-48_p-10\",\"chapterId\":\"han-fei-zi_ch-48\",\"order\":10,\"canonicalText\":\"參言\",\"sentenceIds\":[\"han-fei-zi_ch-48_p-10_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"參言。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈八經〉（第 10 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「參言」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「參言」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-48_p-11\",\"chapterId\":\"han-fei-zi_ch-48\",\"order\":11,\"canonicalText\":\"六、聽不參則無以責下，言不督乎用則邪說當上。言之為物也以多信，不然之物，十人云疑，百人然乎，千人不可解也。吶者言之疑，辯者言之信。姦之食上也，取資乎眾，籍信乎辯，而以類飾其私。人主不饜忿而待合參，其勢資下也。有道之主，聽言、督其用，課其功，功課而賞罰生焉，故無用之辯不留朝。任事者知不足以治職，則放官收。說大而誇則窮端，故姦得而怒。無故而不當為誣，誣而罪，臣言必有報，說必責用也，故朋黨之言不上聞。凡聽之道，人臣忠論以聞姦，博論以內一，人主不智則姦得資。明主之道，己喜則求其所納，己怒則察其所搆；論於已變之後，以得毀譽公私之徵。眾諫以效智故，使君自取一以避罪。故眾之諫也，敗、君之取也。無副言於上以設將然，今符言於後以知謾誠語。明主之道，臣不得兩諫，必任其一語；不得擅行，必合其參；故姦無道進矣。\",\"sentenceIds\":[\"han-fei-zi_ch-48_p-11_s-1\",\"han-fei-zi_ch-48_p-11_s-2\",\"han-fei-zi_ch-48_p-11_s-3\",\"han-fei-zi_ch-48_p-11_s-4\",\"han-fei-zi_ch-48_p-11_s-5\",\"han-fei-zi_ch-48_p-11_s-6\",\"han-fei-zi_ch-48_p-11_s-7\",\"han-fei-zi_ch-48_p-11_s-8\",\"han-fei-zi_ch-48_p-11_s-9\",\"han-fei-zi_ch-48_p-11_s-10\",\"han-fei-zi_ch-48_p-11_s-11\",\"han-fei-zi_ch-48_p-11_s-12\",\"han-fei-zi_ch-48_p-11_s-13\",\"han-fei-zi_ch-48_p-11_s-14\",\"han-fei-zi_ch-48_p-11_s-15\",\"han-fei-zi_ch-48_p-11_s-16\",\"han-fei-zi_ch-48_p-11_s-17\",\"han-fei-zi_ch-48_p-11_s-18\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"六、聽不參則無以責下，言不督乎用則邪說當上。言的為物啊以多信，不然的物，十人云疑，百人然乎，千人不可解啊。吶的人或事物言的疑，辯的人或事物言的信。姦的食上啊，取資乎眾，籍信乎辯，而且以類飾他的私。人主不饜忿而且待合參，他的至高權力威勢資下啊。有道的主，聽言、督他的用，課他的功，功課而且賞賜恩惠刑罰制裁生焉，所以無用的辯不留朝。任事的人或事物知不足以治職，則放官收。說大而且誇則窮端，所以姦得而且怒。無所以而且不當為誣，誣而且罪，臣下僚屬言必有報，說必責用啊，所以朋黨的言不上聞。凡聽的道，人臣下僚屬忠論以聞姦，博論以內一，人主不智則姦得資。明主的道，己喜則求他的所納，己怒則察他的所搆；論於已變的後，以得毀譽公私的徵。眾諫以效智所以，使君主統治者自取一以避罪。所以眾的諫啊，敗、君主統治者的取啊。無副言於上以設將然，今符言於後以知謾誠語。明主的道，臣下僚屬不得兩諫，必任他的一語；不得擅行，必合他的參；所以姦無道進矣。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈八經〉（第 11 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「六、聽不參則無以責下，言不督乎用則邪說當上」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「六、聽不參則無以責下，言不督乎用則邪說當上。言之為物……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-48_p-12\",\"chapterId\":\"han-fei-zi_ch-48\",\"order\":12,\"canonicalText\":\"聽法\",\"sentenceIds\":[\"han-fei-zi_ch-48_p-12_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"聽國家法度法規。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈八經〉（第 12 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「聽法」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「聽法」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-48_p-13\",\"chapterId\":\"han-fei-zi_ch-48\",\"order\":13,\"canonicalText\":\"七、官之重也，毋法也；法之息也，上闇也。上闇無度則官擅為，官擅為故奉重，無前則徵多，徵多故富。官之富重也，亂功之所生也。明主之道，取於任，賢於官，賞於功；言程、主喜俱必利，不當、主怒俱必害，則人不私父兄而進其仇讎。勢足以行法，奉足以給事，而私無所生，故民勞苦而輕官。任事也毋重，使其寵必在爵；處官者毋私，使其利必在祿；故民尊爵而重祿。爵祿所以賞也，民重所以賞也則國治。刑之煩也，名之繆也，賞譽不當則民疑。民之重名與其重賞也均。賞者有誹焉，不足以勸；罰者有譽焉，不足以禁。明主之道，賞必出乎公利，名必在乎為上。賞譽同軌，非誅俱行，然則民無榮於賞之內。有重罰者必有惡名，故民畏。罰所以禁也，民畏所以禁則國治矣。\",\"sentenceIds\":[\"han-fei-zi_ch-48_p-13_s-1\",\"han-fei-zi_ch-48_p-13_s-2\",\"han-fei-zi_ch-48_p-13_s-3\",\"han-fei-zi_ch-48_p-13_s-4\",\"han-fei-zi_ch-48_p-13_s-5\",\"han-fei-zi_ch-48_p-13_s-6\",\"han-fei-zi_ch-48_p-13_s-7\",\"han-fei-zi_ch-48_p-13_s-8\",\"han-fei-zi_ch-48_p-13_s-9\",\"han-fei-zi_ch-48_p-13_s-10\",\"han-fei-zi_ch-48_p-13_s-11\",\"han-fei-zi_ch-48_p-13_s-12\",\"han-fei-zi_ch-48_p-13_s-13\",\"han-fei-zi_ch-48_p-13_s-14\",\"han-fei-zi_ch-48_p-13_s-15\",\"han-fei-zi_ch-48_p-13_s-16\",\"han-fei-zi_ch-48_p-13_s-17\",\"han-fei-zi_ch-48_p-13_s-18\",\"han-fei-zi_ch-48_p-13_s-19\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"七、官的重啊，毋國家法度法規啊；國家法度法規的息啊，上闇啊。上闇無度則官擅為，官擅為所以奉重，無前則徵多，徵多所以富。官的富重啊，亂功的所生啊。明主的道，取於任，賢於官，賞賜恩惠於功；言程、主喜俱必利，不當、主怒俱必害，則人不私父兄而且進他的仇讎。至高權力威勢足以行國家法度法規，奉足以給事，而且私無所生，所以民勞苦而且輕官。任事啊毋重，使他的寵必在爵；處官的人或事物毋私，使他的利必在祿；所以民尊爵而且重祿。爵祿所以賞賜恩惠啊，民重所以賞賜恩惠啊則國治。刑的煩啊，名的繆啊，賞賜恩惠譽不當則民疑。民的重名與他的重賞賜恩惠啊均。賞賜恩惠的人或事物有誹焉，不足以勸；刑罰制裁的人或事物有譽焉，不足以禁。明主的道，賞賜恩惠必出乎公利，名必在乎為上。賞賜恩惠譽同軌，絕不是誅俱行，然則民無榮於賞賜恩惠的內。有重刑罰制裁的人或事物必有惡名，所以民畏。刑罰制裁所以禁啊，民畏所以禁則國治矣。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈八經〉（第 13 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「七、官之重也，毋法也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「七、官之重也，毋法也；法之息也，上闇也。上闇無度則官……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-48_p-14\",\"chapterId\":\"han-fei-zi_ch-48\",\"order\":14,\"canonicalText\":\"類柄\",\"sentenceIds\":[\"han-fei-zi_ch-48_p-14_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"類柄。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈八經〉（第 14 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「類柄」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「類柄」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-48_p-15\",\"chapterId\":\"han-fei-zi_ch-48\",\"order\":15,\"canonicalText\":\"八、行義示則主威分，慈仁聽則法制毀。民以制畏上，而上以勢卑下，故下肆很觸而榮於輕君之俗則主威分。民以法難犯上，而上以法撓慈仁，故下明愛施而務賕紋之政，是以法令隳。尊私行以貳主威，行賕紋以疑法，聽之則亂治，不聽則謗主，故君輕乎位而法亂乎官，此之謂無常之國。明主之道，臣不得以行義成榮，不得以家利為功。功名所生，必出於官法；法之所外，雖有難行，不以顯焉；故民無以私名。設法度以齊民，信賞罰以盡民能，明誹譽以勸沮，名號、賞罰、法令三隅，故大臣有行則尊君，百姓有功則利上，此之謂有道之國也。\",\"sentenceIds\":[\"han-fei-zi_ch-48_p-15_s-1\",\"han-fei-zi_ch-48_p-15_s-2\",\"han-fei-zi_ch-48_p-15_s-3\",\"han-fei-zi_ch-48_p-15_s-4\",\"han-fei-zi_ch-48_p-15_s-5\",\"han-fei-zi_ch-48_p-15_s-6\",\"han-fei-zi_ch-48_p-15_s-7\",\"han-fei-zi_ch-48_p-15_s-8\",\"han-fei-zi_ch-48_p-15_s-9\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"八、行義示則主威分，慈仁聽則國家法度法規制毀。民以制畏上，而且上以至高權力威勢卑下，所以下肆很觸而且榮於輕君主統治者的俗則主威分。民以國家法度法規難犯上，而且上以國家法度法規撓慈仁，所以下明愛施而且務賕紋的政，是以國家法度法規令隳。尊私行以貳主威，行賕紋以疑國家法度法規，聽的則亂治，不聽則謗主，所以君主統治者輕乎位而且國家法度法規亂乎官，此的謂無常的國。明主的道，臣下僚屬不得以行義成榮，不得以家利為功。功名所生，必出於官國家法度法規；國家法度法規的所外，雖有難行，不以顯焉；所以民無以私名。設國家法度法規度以齊民，信賞賜恩惠刑罰制裁以盡民能，明誹譽以勸沮，名號、賞賜恩惠刑罰制裁、國家法度法規令三隅，所以大臣下僚屬有行則尊君主統治者，百姓有功則利上，此的謂有道的國啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈八經〉（第 15 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「八、行義示則主威分，慈仁聽則法制毀」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「八、行義示則主威分，慈仁聽則法制毀。民以制畏上，而上……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}}],\"sentences\":[{\"id\":\"han-fei-zi_ch-48_p-1_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-1\",\"order\":1,\"canonicalText\":\"一、凡治天下，必因人情。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-1_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-1\",\"order\":2,\"canonicalText\":\"人情者，有好惡，故賞罰可用；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-1_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-1\",\"order\":3,\"canonicalText\":\"賞罰可用則禁令可立而治道具矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-1_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-1\",\"order\":4,\"canonicalText\":\"君執柄以處勢，故令行禁止。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-1_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-1\",\"order\":5,\"canonicalText\":\"柄者，殺生之制也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-1_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-1\",\"order\":6,\"canonicalText\":\"勢者，勝眾之資也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-1_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-1\",\"order\":7,\"canonicalText\":\"廢置無度則權瀆，賞罰下共則威分。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-1_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-1\",\"order\":8,\"canonicalText\":\"是以明主不懷愛而聽，不留說而計。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-1_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-1\",\"order\":9,\"canonicalText\":\"故聽言不參則權分乎姦，智力不用則君窮乎臣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-1_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-1\",\"order\":10,\"canonicalText\":\"故明主之行制也天，其用人也鬼。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-1_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-1\",\"order\":11,\"canonicalText\":\"天則不非，鬼則不困。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-1_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-1\",\"order\":12,\"canonicalText\":\"勢行教嚴逆而不違，毀譽一行而不議。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-1_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-1\",\"order\":13,\"canonicalText\":\"故賞賢罰暴，舉善之至者也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-1_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-1\",\"order\":14,\"canonicalText\":\"賞暴罰賢，舉惡之至者也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-1_s-15\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-1\",\"order\":15,\"canonicalText\":\"是謂賞同罰異。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-1_s-16\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-1\",\"order\":16,\"canonicalText\":\"賞莫如厚，使民利之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-1_s-17\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-1\",\"order\":17,\"canonicalText\":\"譽莫如美，使民榮之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-1_s-18\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-1\",\"order\":18,\"canonicalText\":\"誅莫如重，使民畏之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-1_s-19\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-1\",\"order\":19,\"canonicalText\":\"毀莫如惡，使民恥之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-1_s-20\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-1\",\"order\":20,\"canonicalText\":\"然後一行其法，禁誅於私。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-1_s-21\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-1\",\"order\":21,\"canonicalText\":\"家不害功罪，賞罰必知之，知之道盡矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-2_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-2\",\"order\":1,\"canonicalText\":\"因情\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-3_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-3\",\"order\":1,\"canonicalText\":\"二、力不敵眾，智不盡物。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-3_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-3\",\"order\":2,\"canonicalText\":\"與其用一人，不如用一國。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-3_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-3\",\"order\":3,\"canonicalText\":\"故智力敵而羣物勝，揣中則私勞，不中則在過。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-3_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-3\",\"order\":4,\"canonicalText\":\"下君盡己之能，中君盡人之力，上君盡人之智。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-3_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-3\",\"order\":5,\"canonicalText\":\"是以事至而結智，一聽而公會。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-3_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-3\",\"order\":6,\"canonicalText\":\"聽不一則後悖於前，後悖於前則愚智不分；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-3_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-3\",\"order\":7,\"canonicalText\":\"不公會則猶豫而不斷，不斷則事留。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-3_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-3\",\"order\":8,\"canonicalText\":\"自取一，則毋墮壑之累。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-3_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-3\",\"order\":9,\"canonicalText\":\"故使之諷，諷定而怒。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-3_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-3\",\"order\":10,\"canonicalText\":\"是以言陳之日，必有筴籍，結智者事發而驗，結能者功見而。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-3_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-3\",\"order\":11,\"canonicalText\":\"謀成敗，成敗有徵，賞罰隨之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-3_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-3\",\"order\":12,\"canonicalText\":\"事成則君收其功，規敗則臣任其罪。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-3_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-3\",\"order\":13,\"canonicalText\":\"君人者合符猶不親，而況於力乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-3_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-3\",\"order\":14,\"canonicalText\":\"事智猶不親，而況於懸乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-3_s-15\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-3\",\"order\":15,\"canonicalText\":\"故非用人也不取同，同則君怒。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-3_s-16\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-3\",\"order\":16,\"canonicalText\":\"使人相用則君神，君神則下盡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-3_s-17\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-3\",\"order\":17,\"canonicalText\":\"下盡下，則臣、上不因君而主道畢矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-4_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-4\",\"order\":1,\"canonicalText\":\"主道\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":1,\"canonicalText\":\"三、知臣主之異利者王，以為同者劫，與共事者殺。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":2,\"canonicalText\":\"故明主審公私之分，審利害之地，姦乃無所乘。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":3,\"canonicalText\":\"亂之所生六也：主母，後姬，子姓，弟兄，大臣，顯賢。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":4,\"canonicalText\":\"任吏責臣，主母不放。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":5,\"canonicalText\":\"禮施異等，後姬不疑。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":6,\"canonicalText\":\"分勢不貳，庶適不爭。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":7,\"canonicalText\":\"權籍不失，兄弟不侵。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":8,\"canonicalText\":\"下不一門，大臣不擁。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":9,\"canonicalText\":\"禁賞必行，顯賢不亂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":10,\"canonicalText\":\"臣有二因，謂外內也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":11,\"canonicalText\":\"外曰畏，內曰愛。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":12,\"canonicalText\":\"所畏之求得，所愛之言聽，此亂臣之所因也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":13,\"canonicalText\":\"外國之置諸吏者，結誅親暱重帑，則外不籍矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":14,\"canonicalText\":\"爵祿循功，請者俱罪，則內不因矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-15\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":15,\"canonicalText\":\"外不籍，內不因，則姦宄塞矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-16\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":16,\"canonicalText\":\"官襲節而進，以至大任，智也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-17\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":17,\"canonicalText\":\"其位至而任大者，以三節持之，曰質、曰鎮、曰固。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-18\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":18,\"canonicalText\":\"親戚妻子，質也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-19\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":19,\"canonicalText\":\"爵祿厚而必，鎮也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-20\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":20,\"canonicalText\":\"參伍貴帑，固也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-21\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":21,\"canonicalText\":\"賢者止於質，貪饕化於鎮，姦邪窮於固。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-22\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":22,\"canonicalText\":\"忍不制則下上，小不除則大誅，而名實當則徑之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-23\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":23,\"canonicalText\":\"生害事，死傷名，則行飲食；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-24\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":24,\"canonicalText\":\"不然，而與其讎；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-25\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":25,\"canonicalText\":\"此謂除陰姦也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-26\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":26,\"canonicalText\":\"醫曰詭，詭曰易。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-27\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":27,\"canonicalText\":\"易功而賞，見罪而罰，而詭乃止。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-28\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":28,\"canonicalText\":\"是非不泄，說諫不通，而易乃不用。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-29\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":29,\"canonicalText\":\"父兄賢良播出曰遊禍，其患鄰敵多資。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-30\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":30,\"canonicalText\":\"僇辱之人近習曰狎賊，其患發忿疑辱之心生。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-31\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":31,\"canonicalText\":\"藏怒持罪而不發曰增亂，其患徼倖妄舉之人起。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-32\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":32,\"canonicalText\":\"大臣兩重、提衡而不踦曰卷禍，其患家隆劫殺之難作。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-33\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":33,\"canonicalText\":\"脫易不自神曰彈威，其患賊夫酖毒之亂起。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-34\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":34,\"canonicalText\":\"此五患者，人主之不知，則有劫殺之事。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-35\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":35,\"canonicalText\":\"廢置之事，生於內則治，生於外則亂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-36\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":36,\"canonicalText\":\"是以明主以功論之內，而以利資之外，故其國治而敵亂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-5_s-37\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-5\",\"order\":37,\"canonicalText\":\"即亂之道，臣憎則起外若眩，臣愛則起內若藥。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-6_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-6\",\"order\":1,\"canonicalText\":\"起亂\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-7_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-7\",\"order\":1,\"canonicalText\":\"四、參伍之道：行參以謀多，揆伍以責失；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-7_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-7\",\"order\":2,\"canonicalText\":\"行參必拆，揆伍必怒。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-7_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-7\",\"order\":3,\"canonicalText\":\"不拆則瀆上，不怒則相和。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-7_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-7\",\"order\":4,\"canonicalText\":\"拆之徵足以知多寡，怒之前不及其眾。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-7_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-7\",\"order\":5,\"canonicalText\":\"觀聽之勢，其徵在比周而賞異也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-7_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-7\",\"order\":6,\"canonicalText\":\"誅毋謁而罪同。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-7_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-7\",\"order\":7,\"canonicalText\":\"言會眾端，必揆之以地，謀之以天，驗之以物，參之以人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-7_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-7\",\"order\":8,\"canonicalText\":\"四徵者符，乃可以觀矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-7_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-7\",\"order\":9,\"canonicalText\":\"參言以知其誠，易視以改其澤。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-7_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-7\",\"order\":10,\"canonicalText\":\"執見以得非常。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-7_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-7\",\"order\":11,\"canonicalText\":\"一用以務近習，重言以懼遠使，舉往以悉其前，即邇以知其內，疏置以知其外，握明以問所闇，詭使以絕黷泄，倒言以嘗所疑，論反以得陰姦，設諫以綱獨為，舉錯以觀姦動，明說以誘避過，卑適以觀直諂，宣聞以通未見，作鬥以散朋黨，深一以警眾心，泄異以易其慮。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-7_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-7\",\"order\":12,\"canonicalText\":\"似類則合其參，陳過則明其固，知罪闢罪以止威，陰使時循以省衰，漸更以離通比，下約以侵其上，相室約其廷臣，廷臣約其官屬，兵士約其軍吏，遣使約其行介，縣令約其闢吏，郎中約其左右，後姬約其宮媛，此之謂條達之道。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-7_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-7\",\"order\":13,\"canonicalText\":\"言通事泄則術不行。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-8_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-8\",\"order\":1,\"canonicalText\":\"立道\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-9_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-9\",\"order\":1,\"canonicalText\":\"五、明主，其務在周密。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-9_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-9\",\"order\":2,\"canonicalText\":\"是以喜見則德償，怒見則威分。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-9_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-9\",\"order\":3,\"canonicalText\":\"故明主之言隔塞而不通，周密而不見。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-9_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-9\",\"order\":4,\"canonicalText\":\"故以一得十者下道也，以十得一者上道也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-9_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-9\",\"order\":5,\"canonicalText\":\"明主兼行上下，故姦無所失。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-9_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-9\",\"order\":6,\"canonicalText\":\"伍、官、連、縣而鄰，謁過賞，失過誅。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-9_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-9\",\"order\":7,\"canonicalText\":\"上之於下，下之於上，亦然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-9_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-9\",\"order\":8,\"canonicalText\":\"是故上下貴賤相畏以法，相誨以和。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-9_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-9\",\"order\":9,\"canonicalText\":\"民之性，有生之實，有生之名。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-9_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-9\",\"order\":10,\"canonicalText\":\"為君者有賢知之名，有賞罰之實。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-9_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-9\",\"order\":11,\"canonicalText\":\"名實俱至，故福善必聞矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-10_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-10\",\"order\":1,\"canonicalText\":\"參言\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-11_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-11\",\"order\":1,\"canonicalText\":\"六、聽不參則無以責下，言不督乎用則邪說當上。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-11_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-11\",\"order\":2,\"canonicalText\":\"言之為物也以多信，不然之物，十人云疑，百人然乎，千人不可解也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-11_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-11\",\"order\":3,\"canonicalText\":\"吶者言之疑，辯者言之信。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-11_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-11\",\"order\":4,\"canonicalText\":\"姦之食上也，取資乎眾，籍信乎辯，而以類飾其私。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-11_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-11\",\"order\":5,\"canonicalText\":\"人主不饜忿而待合參，其勢資下也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-11_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-11\",\"order\":6,\"canonicalText\":\"有道之主，聽言、督其用，課其功，功課而賞罰生焉，故無用之辯不留朝。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-11_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-11\",\"order\":7,\"canonicalText\":\"任事者知不足以治職，則放官收。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-11_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-11\",\"order\":8,\"canonicalText\":\"說大而誇則窮端，故姦得而怒。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-11_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-11\",\"order\":9,\"canonicalText\":\"無故而不當為誣，誣而罪，臣言必有報，說必責用也，故朋黨之言不上聞。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-11_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-11\",\"order\":10,\"canonicalText\":\"凡聽之道，人臣忠論以聞姦，博論以內一，人主不智則姦得資。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-11_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-11\",\"order\":11,\"canonicalText\":\"明主之道，己喜則求其所納，己怒則察其所搆；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-11_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-11\",\"order\":12,\"canonicalText\":\"論於已變之後，以得毀譽公私之徵。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-11_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-11\",\"order\":13,\"canonicalText\":\"眾諫以效智故，使君自取一以避罪。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-11_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-11\",\"order\":14,\"canonicalText\":\"故眾之諫也，敗、君之取也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-11_s-15\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-11\",\"order\":15,\"canonicalText\":\"無副言於上以設將然，今符言於後以知謾誠語。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-11_s-16\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-11\",\"order\":16,\"canonicalText\":\"明主之道，臣不得兩諫，必任其一語；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-11_s-17\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-11\",\"order\":17,\"canonicalText\":\"不得擅行，必合其參；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-11_s-18\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-11\",\"order\":18,\"canonicalText\":\"故姦無道進矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-12_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-12\",\"order\":1,\"canonicalText\":\"聽法\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-13_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-13\",\"order\":1,\"canonicalText\":\"七、官之重也，毋法也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-13_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-13\",\"order\":2,\"canonicalText\":\"法之息也，上闇也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-13_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-13\",\"order\":3,\"canonicalText\":\"上闇無度則官擅為，官擅為故奉重，無前則徵多，徵多故富。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-13_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-13\",\"order\":4,\"canonicalText\":\"官之富重也，亂功之所生也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-13_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-13\",\"order\":5,\"canonicalText\":\"明主之道，取於任，賢於官，賞於功；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-13_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-13\",\"order\":6,\"canonicalText\":\"言程、主喜俱必利，不當、主怒俱必害，則人不私父兄而進其仇讎。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-13_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-13\",\"order\":7,\"canonicalText\":\"勢足以行法，奉足以給事，而私無所生，故民勞苦而輕官。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-13_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-13\",\"order\":8,\"canonicalText\":\"任事也毋重，使其寵必在爵；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-13_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-13\",\"order\":9,\"canonicalText\":\"處官者毋私，使其利必在祿；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-13_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-13\",\"order\":10,\"canonicalText\":\"故民尊爵而重祿。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-13_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-13\",\"order\":11,\"canonicalText\":\"爵祿所以賞也，民重所以賞也則國治。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-13_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-13\",\"order\":12,\"canonicalText\":\"刑之煩也，名之繆也，賞譽不當則民疑。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-13_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-13\",\"order\":13,\"canonicalText\":\"民之重名與其重賞也均。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-13_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-13\",\"order\":14,\"canonicalText\":\"賞者有誹焉，不足以勸；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-13_s-15\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-13\",\"order\":15,\"canonicalText\":\"罰者有譽焉，不足以禁。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-13_s-16\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-13\",\"order\":16,\"canonicalText\":\"明主之道，賞必出乎公利，名必在乎為上。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-13_s-17\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-13\",\"order\":17,\"canonicalText\":\"賞譽同軌，非誅俱行，然則民無榮於賞之內。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-13_s-18\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-13\",\"order\":18,\"canonicalText\":\"有重罰者必有惡名，故民畏。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-13_s-19\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-13\",\"order\":19,\"canonicalText\":\"罰所以禁也，民畏所以禁則國治矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-14_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-14\",\"order\":1,\"canonicalText\":\"類柄\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-15_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-15\",\"order\":1,\"canonicalText\":\"八、行義示則主威分，慈仁聽則法制毀。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-15_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-15\",\"order\":2,\"canonicalText\":\"民以制畏上，而上以勢卑下，故下肆很觸而榮於輕君之俗則主威分。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-15_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-15\",\"order\":3,\"canonicalText\":\"民以法難犯上，而上以法撓慈仁，故下明愛施而務賕紋之政，是以法令隳。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-15_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-15\",\"order\":4,\"canonicalText\":\"尊私行以貳主威，行賕紋以疑法，聽之則亂治，不聽則謗主，故君輕乎位而法亂乎官，此之謂無常之國。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-15_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-15\",\"order\":5,\"canonicalText\":\"明主之道，臣不得以行義成榮，不得以家利為功。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-15_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-15\",\"order\":6,\"canonicalText\":\"功名所生，必出於官法；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-15_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-15\",\"order\":7,\"canonicalText\":\"法之所外，雖有難行，不以顯焉；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-15_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-15\",\"order\":8,\"canonicalText\":\"故民無以私名。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-48_p-15_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-48\",\"passageId\":\"han-fei-zi_ch-48_p-15\",\"order\":9,\"canonicalText\":\"設法度以齊民，信賞罰以盡民能，明誹譽以勸沮，名號、賞罰、法令三隅，故大臣有行則尊君，百姓有功則利上，此之謂有道之國也。\",\"chunks\":[],\"tags\":[]}]}") as ChapterBundle
